// Bilingual glossary and acronym decoder for ISO 19650 / BIM practice.
// Definitions are plain-English paraphrases (UK spelling), never quotations of a standard.
// Arabic is professional MSA as used by BIM practitioners in the Gulf and Egypt.
// The Glossary page shows both languages side by side, so the Arabic lives here rather than in locales/ar.json.

export type GlossaryCategory =
  | "ISO 19650 process"
  | "Information requirements"
  | "CDE & status"
  | "Documents & plans"
  | "Models & data"
  | "Open standards (IFC, BCF, IDS, COBie)"
  | "Roles & parties"
  | "Security & H&S"
  | "Operations & assets"
  | "AI & digital"
  | "Contracts & procurement"
  | "General construction";

export interface GlossaryEntry {
  term: string;
  abbr?: string;
  ar: string;
  arAbbr?: string;
  definition: string;
  definitionAr: string;
  category: GlossaryCategory;
  related?: string[];
  source?: string;
}

export const GLOSSARY_CATEGORIES: GlossaryCategory[] = [
  "ISO 19650 process", "Information requirements", "CDE & status", "Documents & plans", "Models & data",
  "Open standards (IFC, BCF, IDS, COBie)", "Roles & parties", "Security & H&S", "Operations & assets",
  "AI & digital", "Contracts & procurement", "General construction",
];

// [term, abbr ("" = none), Arabic term, definition, Arabic definition, related?, source?]
type Row = [string, string, string, string, string, string[]?, string?];

const rows = (category: GlossaryCategory, list: Row[]): GlossaryEntry[] =>
  list.map(([term, abbr, ar, definition, definitionAr, related, source]) => ({
    term, ...(abbr ? { abbr } : {}), ar, definition, definitionAr, category,
    ...(related && related.length ? { related } : {}), ...(source ? { source } : {}),
  }));

